public void Main(Scanner sc) {
    // Input
    int n = sc.nextInt();
    int m = sc.nextInt();
    sc.nextLine();

    List<Integer> a = new ArrayList<>();
    List<Integer> b = new ArrayList<>();

    for (int i = 0; i < n; i++) {
        a.add(sc.nextInt());
    }
    sc.nextLine();
    for (int i = 0; i < m; i++) {
        b.add(sc.nextInt());
    }

    // Combine sequences A and B into C
    List<Integer> c = new ArrayList<>(a);
    c.addAll(b);

    // Sort sequence C
    Collections.sort(c);

    // Check for two consecutive elements from sequence A
    for (int i = 0; i < c.size() - 1; i++) {
        if (a.contains(c.get(i)) && a.contains(c.get(i + 1))) {
            System.out.println("Yes");
            return;
        }
    }

    System.out.println("No");
}
